for slug,items in replacements.items():
 seen=set();duplicates=[]
 for q in BANK[slug]:
  key=' '.join(q['prompt'].split()).lower()
  if key in seen:duplicates.append(q['id'])
  seen.add(key)
 assert len(duplicates)==len(items),(slug,len(duplicates),len(items))
 for i,item in zip(duplicates,items):replace(slug,i,*item)
