for slug,bank in BANK.items():
 for q in bank:
  # Remove PDF wrapping in prose, while keeping actual tables and their row breaks.
  if '|' not in q['prompt']:q['prompt']=' '.join(q['prompt'].split())
  q['prompt']=q['prompt'].replace('graph above','figure below').replace('graphs above','figures below')
  for o in q['options']:
   o['text']=re.sub(r'\s+(?:under the stated conditions|in the market described|when other factors are unchanged|at the relevant margin)\.?$','',o['text']).strip().rstrip('.')
   if o['text'] and o['text'][0].islower():o['text']=o['text'][0].upper()+o['text'][1:]
  q['reference']=re.sub(r' \| POL-2\.A\.1.*? \| Skill',' | Skill',q['reference'])
# Remaining exact-duplicate prompts in other units are handled separately before shuffling.
